<script setup>
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { useRouter } from 'vue-router'
import { fetchSeoKeywords,fetchSeoOverview } from '../../api/seo'
import { currentTenantId } from '../../store/session'
const router=useRouter(),loading=ref(false),error=ref(''),engine=ref('baidu'),filters=reactive({q:'',priority:'',alerts:false}),result=ref({items:[],total:0}),overview=ref({stats:{}})
const engines=[{k:'baidu',n:'百度'},{k:'google',n:'Google'},{k:'bing',n:'Bing'}]
const rows=computed(()=>result.value.items.filter(i=>(!filters.priority||i.priority===filters.priority)&&(!filters.alerts||i.rank_delta<0)))
const ranked=computed(()=>result.value.items.filter(i=>i.latest_rank!=null)),avg=computed(()=>ranked.value.length?(ranked.value.reduce((s,i)=>s+i.latest_rank,0)/ranked.value.length).toFixed(1):'—')
const fmt=v=>v==null?'—':Number(v).toLocaleString('zh-CN')
function delta(i){return !i.rank_delta?'—':`${i.rank_delta>0?'↑':'↓'}${Math.abs(i.rank_delta)}`}
function spark(i){if(i.latest_rank==null)return'';const previous=Math.max(1,i.latest_rank+(i.rank_delta||0));const max=Math.max(previous,i.latest_rank,10);return `2,${2+previous/max*24} 90,${2+i.latest_rank/max*24}`}
function exportCsv(){const data=[['关键词','优先级','当前排名','周期变化','月搜索量','承接页面'],...rows.value.map(i=>[i.keyword,i.priority,i.latest_rank||'',i.rank_delta||0,i.monthly_volume||0,i.landing_page||''])];const blob=new Blob(['\ufeff'+data.map(r=>r.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`SEO排名-${engine.value}.csv`;a.click();URL.revokeObjectURL(a.href)}
const window={print:exportCsv}
async function load(){if(!currentTenantId.value){error.value='请先选择客户';return}loading.value=true;try{[result.value,overview.value]=await Promise.all([fetchSeoKeywords({tenantId:currentTenantId.value,q:filters.q,engine:engine.value,pageSize:200}),fetchSeoOverview({tenantId:currentTenantId.value,engine:engine.value})]);error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
let timer;watch(()=>filters.q,()=>{clearTimeout(timer);timer=setTimeout(load,260)});watch([engine,currentTenantId],load);onMounted(load)
</script>
<template><div class="keyword-assets ranking-prototype" v-loading="loading"><section class="kw-hero"><div><div class="kw-kicker">Ranking monitor</div><h2>排名监控</h2><p>按搜索引擎查看自然排名、周期变化与承接页，优先处理排名骤降和进入首页临界区的关键词。</p></div><div class="kw-actions"><button class="kw-btn" @click="window.print()">⇩ 导出排名</button><button class="kw-btn primary" @click="load">↻ 更新排名</button></div></section><el-alert v-if="error" :title="error" type="warning" :closable="false"/><section class="kw-metrics"><article class="kw-metric" data-mark="K"><span>监控关键词</span><strong>{{fmt(result.total)}}</strong><small>自然搜索关键词资产</small></article><article class="kw-metric" data-mark="R"><span>平均自然排名</span><strong>{{avg}}</strong><small class="up">排名越小越好</small></article><article class="kw-metric" data-mark="10"><span>前 10 名</span><strong>{{fmt(overview.stats?.top10)}}</strong><small class="up">首页覆盖率 {{overview.stats?.top10_rate||0}}%</small></article><article class="kw-metric" data-mark="Δ"><span>本期净提升</span><strong>{{ranked.filter(i=>i.rank_delta>0).length-ranked.filter(i=>i.rank_delta<0).length}}</strong><small>上涨减下跌</small></article></section><section class="kw-card"><header class="kw-card-head"><div><h3>自然排名明细</h3><p>最近排名快照 · 桌面端 · 全国</p></div><div class="kw-segment"><button v-for="item in engines" :key="item.k" :class="{active:engine===item.k}" @click="engine=item.k">{{item.n}}</button></div></header><div class="kw-card-body"><div class="kw-toolbar"><div class="kw-search"><input v-model="filters.q" class="kw-input" placeholder="搜索监控关键词"></div><select v-model="filters.priority" class="kw-select"><option value="">全部优先级</option><option v-for="p in ['P0','P1','P2','P3']" :key="p">{{p}}</option></select><button class="kw-btn ghost" :class="{active:filters.alerts}" @click="filters.alerts=!filters.alerts">仅看异常 {{result.items.filter(i=>i.rank_delta<0).length}}</button></div></div><div class="kw-table-wrap"><table class="kw-table"><thead><tr><th>关键词</th><th>优先级</th><th>当前排名</th><th>周期趋势</th><th>月搜索量</th><th>承接页面</th><th>状态</th><th>详情</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td class="keyword-cell"><span class="kw-name"><button @click="router.push(`/seo/keywords/${row.id}`)">{{row.keyword}}</button></span><small class="kw-sub">{{row.cluster||'未归类'}}</small></td><td><span class="kw-priority" :class="row.priority.toLowerCase()">{{row.priority}}</span></td><td><span class="kw-rank"><strong>{{row.latest_rank||'100+'}}</strong><i :class="row.rank_delta>0?'up':row.rank_delta<0?'down':''">{{delta(row)}}</i></span></td><td><svg v-if="spark(row)" width="92" height="28" viewBox="0 0 92 28"><polyline :points="spark(row)" fill="none" :stroke="row.rank_delta>=0?'#248a64':'#d9544d'" stroke-width="2"/></svg><span v-else>—</span></td><td>{{fmt(row.monthly_volume)}}</td><td><div class="kw-link">{{row.landing_page||'—'}}</div></td><td><span class="kw-pill" :class="row.rank_delta<0?'red':row.rank_delta>0?'green':'gray'">{{row.rank_delta<0?'排名波动':row.rank_delta>0?'增长机会':'稳定'}}</span></td><td><button class="kw-btn small" @click="router.push(`/seo/keywords/${row.id}`)">查看历史 →</button></td></tr><tr v-if="!rows.length"><td colspan="8"><div class="kw-empty"><b>暂无排名数据</b>导入排名快照后生成</div></td></tr></tbody></table></div></section></div></template>
<style>@import url('/deal-sniper-prototype/seo/assets/keyword-assets-v2.css');</style>
<style scoped>.ranking-prototype{min-height:100%;padding:22px 26px 30px;background:#f5f7fb}.kw-name button{padding:0;border:0;background:none;color:#2457d6;font-weight:700;cursor:pointer}.kw-btn.active{border-color:#d9544d;color:#d9544d}</style>
